contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount, address other) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient balance");
        require(other != address(this), "observer must differ from caller");
        c.addToBalance{value: amount}(); if (__ESBMC_reverted()) return;

        uint256 beforeCallerBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeOtherBalance = c.getBalance(other); if (__ESBMC_reverted()) return;
        uint256 beforeContractEther = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterCallerBalance = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterOtherBalance = c.getBalance(other); if (__ESBMC_reverted()) return;
        uint256 afterContractEther = address(c).balance;

        assert(
            beforeCallerBalance > beforeContractEther
                ? (reverted && afterCallerBalance == beforeCallerBalance && afterOtherBalance == beforeOtherBalance && afterContractEther == beforeContractEther)
                : (!reverted && afterCallerBalance == 0 && afterOtherBalance == beforeOtherBalance && afterContractEther == beforeContractEther - beforeCallerBalance)
        );
    }

    receive() external payable {}
}

