pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount, address other) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(other != address(this));
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 beforeCallerBalance;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeCallerBalance = __r; } catch { return; }
        uint256 beforeOtherBalance;
        try c.getBalance(other) returns (uint256 __r) { beforeOtherBalance = __r; } catch { return; }
        uint256 beforeContractEther = address(c).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterCallerBalance;
        try c.getBalance(address(this)) returns (uint256 __r) { afterCallerBalance = __r; } catch { return; }
        uint256 afterOtherBalance;
        try c.getBalance(other) returns (uint256 __r) { afterOtherBalance = __r; } catch { return; }
        uint256 afterContractEther = address(c).balance;
        assertTrue(beforeCallerBalance > beforeContractEther
                ? (reverted && afterCallerBalance == beforeCallerBalance && afterOtherBalance == beforeOtherBalance && afterContractEther == beforeContractEther)
                : (!reverted && afterCallerBalance == 0 && afterOtherBalance == beforeOtherBalance && afterContractEther == beforeContractEther - beforeCallerBalance));
    }

    function testFuzz_run(uint256 amount, address other) public {
        vm.assume(other.code.length == 0 && uint160(other) > 0xffff && other != address(this) && other != address(c) && other != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && other != 0x000000000000000000636F6e736F6c652e6c6f67 && other != 0x4e59b44847b379578588920cA78FbF26c0B4956C && other != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(amount, other);
    }

    receive() external payable {}
}
